import numpy as np
import sys

sys.path.append('storage/cognito')

try:
    from force_directed_v1 import run_fdi_simulation
except ImportError:
    print("Error: Could not import force_directed_v1.py from storage/cognito.")
    def run_fdi_simulation(seed=0): return None, None

def construct_packing() -> tuple:
    N_CIRCLES = 32

    centers, radii = run_fdi_simulation(seed=123)

    if centers is not None and radii is not None:
      # Apply a safety shrink, as is good practice
      final_radii = radii * (1.0 - 1e-8)
      return centers, final_radii
    else:
      print("Algorithm failed, returning fallback packing.")
      return np.array([[0.1 + i*0.01, 0.1] for i in range(N_CIRCLES)]), np.full(N_CIRCLES, 0.001)
